"""System theme target: foot.

Renders foot.ini, the terminal's font and colours, into the theme state
directory. The vendor fragment (desktop/defaults/foot.ini, included from
~/.config/foot/foot.ini) carries the default dark theme as a fallback and
includes this file last, so these values win. foot names its palettes
[colors-dark] and [colors-light]; both get the shell's current one, whichever
foot shows.

foot reads its configuration when a window starts; running windows keep their
colours until they are reopened.
"""
import theme_terminal

NAME = 'foot'

HEADER = (
    '# Generated by theme-apply.py (scripts/theme_foot.py) from the shell\'s\n'
    '# appearance tokens. Rewritten whenever the appearance changes: put colour\n'
    '# or font overrides in ~/.config/foot/foot.ini instead.\n'
)


def palette(tokens):
    colors = theme_terminal.colors(tokens)
    plain = {key: value[1:] for key, value in colors.items() if key != 'ansi'}
    pairs = [
        ('foreground', plain['foreground']),
        ('background', plain['background']),
        ('selection-foreground', plain['selection_foreground']),
        ('selection-background', plain['selection_background']),
        ('cursor', f'{plain["cursor_text"]} {plain["cursor"]}'),
        ('urls', plain['url']),
    ]
    pairs.extend((f'regular{index}', value[1:]) for index, value in enumerate(colors['ansi'][:8]))
    pairs.extend((f'bright{index}', value[1:]) for index, value in enumerate(colors['ansi'][8:]))
    return pairs


def render(tokens):
    body = ''.join(f'{key}={value}\n' for key, value in palette(tokens))
    font = f'font={theme_terminal.FONT_FAMILY}:size={theme_terminal.font_size(tokens)}\n'
    return {'foot.ini': HEADER + '[main]\n' + font + '\n[colors-dark]\n' + body + '\n[colors-light]\n' + body}


